sp_ListarItensPedido	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_ListarItensPedido`(p_idPedido INT)\nBEGIN\n\n    SELECT\n\n        pi.idPedidoItem,\n\n        pi.idPedido,\n\n        pi.idProduto,\n\n        p.Nome        AS nomeProduto,\n\n        p.codProduto  AS skuProduto,\n\n        pi.quantidade,\n\n        pi.valorUnitario,\n\n        pi.desconto,\n\n        pi.valorTotal\n\n    FROM PedidoItem pi\n\n    INNER JOIN Produto p ON p.idProduto = pi.idProduto\n\n    WHERE pi.idPedido = p_idPedido;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
